-- Idempotent source-only update. Retains existing IDs, counters and enabled preferences.
with incoming as (select * from jsonb_to_recordset('[{"name":"Milton Huse","domain":"https://miltonhuse.dk/karriere","source_group":"Construction/Housebuilders"},{"name":"ABC Pavilloner","domain":"https://abcpavilloner.dk/job/ledige-stillinger/","source_group":"Construction/Modular"},{"name":"Adapteo Danmark","domain":"https://adapteo.com/careers/join-us","source_group":"Construction/Modular"},{"name":"Topdahl","domain":"https://topdahl.dk/ledige-stillinger-indenfor-bygningsraadgivning-og-energioptimering/","source_group":"SME/Engineering"},{"name":"Ingeniørfirmaet J&P","domain":"https://www.jogp.dk/","source_group":"SME/Engineering"},{"name":"BLOKK","domain":"https://blokk.dk/nyheder/","source_group":"SME/Architecture"},{"name":"Friis Andersen Arkitekter","domain":"https://friis-a.dk/node/425","source_group":"SME/Architecture"},{"name":"Gråkjær","domain":"https://graakjaer.dk/karriere","source_group":"Construction/Contractors"},{"name":"DS Flexhal","domain":"https://www.ds-flexhal.dk/da-dk/jobs-1","source_group":"Construction/Contractors"},{"name":"BILA","domain":"https://www.bila.dk/om-bila/karriere/ledige-stillinger/","source_group":"Industry/Technical"},{"name":"DIS/CREADIS","domain":"https://creadis.com/our-vacancies/","source_group":"Engineering/Technical"},{"name":"Daikin Denmark","domain":"https://www.daikin.dk/dk_dk/stillinger.html","source_group":"Industry/Technical"},{"name":"Danfoss","domain":"https://www.danfoss.com/da-dk/about-danfoss/careers/","source_group":"Industry/Technical"},{"name":"Grundfos","domain":"https://jobs.grundfos.com/","source_group":"Industry/Technical"},{"name":"ROCKWOOL","domain":"https://www.rockwool.com/group/about-us/careers/vacancies/","source_group":"Industry/Technical"},{"name":"VELUX","domain":"https://www.velux.com/company/career","source_group":"Industry/Technical"},{"name":"Schneider Electric","domain":"https://www.se.com/dk/da/about-us/careers/overview/","source_group":"Industry/Technical"},{"name":"Salling Group","domain":"https://sallinggroup.com/job/ledige-stillinger","source_group":"Retail/Facilities"},{"name":"Forenede Service","domain":"https://www.forenedeservice.dk/ledige-stillinger/","source_group":"Facilities/Cleaning"},{"name":"Kongsvang Cleaning & Facility","domain":"https://kongsvang.net/job-og-karriere/karriere/","source_group":"Facilities/Cleaning"},{"name":"Servicefirmaet Renell","domain":"https://www.renell.dk/ledig-stillinger/","source_group":"Facilities/Cleaning"},{"name":"RENLIG Rengøring & Service","domain":"https://www.renligservice.dk/job","source_group":"SME/Cleaning"},{"name":"Rengøringsagenterne","domain":"https://ren-agenterne.dk/job-dk/cleaning/","source_group":"SME/Cleaning"},{"name":"FRIIS Rengøring","domain":"https://friis-ren.dk/om-friis/karriere/","source_group":"Facilities/Cleaning"},{"name":"Four FM","domain":"https://fourfmab.teamtailor.com/jobs","source_group":"Facilities/Coordination"},{"name":"Eurofins Danmark","domain":"https://careers.smartrecruiters.com/Eurofins","source_group":"Life Science/Services"},{"name":"DSV","domain":"https://jobs.dsv.com/?locale=da_DK","source_group":"Transport/Logistics"},{"name":"GLS Denmark","domain":"https://karriere.gls.dk/da/soeg-job","source_group":"Transport/Logistics"},{"name":"Bring Danmark","domain":"https://www.bring.dk/job","source_group":"Transport/Logistics"},{"name":"PostNord Danmark","domain":"https://group.postnord.com/da/careers/ledige-job/","source_group":"Transport/Logistics"},{"name":"Coor","domain":"https://www.coor.dk/job/ledige-jobs/","source_group":"Property/Facilities"},{"name":"ABC Rådgivende Ingeniører","domain":"https://abc.dk/karriere","source_group":"Engineering/BIM/Consulting"},{"name":"Norconsult","domain":"https://norconsult.dk/karriere/ledige-stillinger/","source_group":"Employers"},{"name":"Sweco","domain":"https://www.sweco.dk/karriere-hos-sweco/ledige-stillinger/","source_group":"Employers"}]'::jsonb) as x(name text,domain text,source_group text)),
updated as (update public.job_sources s set domain=i.domain from incoming i where s.user_id='2ee8af42-ff93-4f05-b1ff-00909eec6f46' and lower(s.name)=lower(i.name) and s.domain is distinct from i.domain and not exists(select 1 from public.job_sources other where other.user_id=s.user_id and other.id<>s.id and other.domain=i.domain) returning s.name),
inserted as (insert into public.job_sources(user_id,name,domain,source_group,enabled) select '2ee8af42-ff93-4f05-b1ff-00909eec6f46',i.name,i.domain,i.source_group,true from incoming i where not exists(select 1 from public.job_sources s where s.user_id='2ee8af42-ff93-4f05-b1ff-00909eec6f46' and (lower(s.name)=lower(i.name) or lower(rtrim(s.domain,'/'))=lower(rtrim(i.domain,'/')))) on conflict(user_id,domain) do nothing returning name)
select jsonb_build_object('inserted',(select jsonb_agg(name) from inserted),'updated',(select jsonb_agg(name) from updated),'added_count',(select count(*) from inserted),'updated_count',(select count(*) from updated)) as expansion;
